console.log('A');
setTimeout(() => {
  console.log('B');
}, 0);
Promise.resolve().then(() => {
  console.log('C');
});
console.log('D');

async function go() {
  console.log('A');
  await null;
  console.log('B');
}
go();
console.log('C');

async function go() {
  for (const n of [1, 2]) {
    await n;
    console.log(n);
  }
}
go();
console.log('end');

new Promise((resolve) => {
  console.log("in");
  resolve();
}).then(
  () => console.log("then"));
console.log("after");

for (var i = 0; i < 3; i++) {
  setTimeout(() =>
    console.log(i));
}

for (let i = 0; i < 3; i++) {
  setTimeout(() =>
    console.log(i));
}

function make() {
  let n = 0;
  return () => ++n;
}
const a = make();
const b = make();
console.log(a(), a(), b());

const a = [1, 2, 3];
console.log(a.map((n) => n * 2));
console.log(
  a.forEach((n) => n * 2));

const a = [1, 2, 3, 4];
console.log(
  a.reduce((t, n) => t + n, 10)
);

const a = [3, 1, 2];
const b = a.sort();
b.push(4);
console.log(a);

const a = [{ n: 1 }];
const b = [...a];
b[0].n = 9;
console.log(a[0].n);

const { a = 1, b = 2 } =
  { a: undefined, b: null };
console.log(a, b);

const o = {
  n: 1,
  normal() { return this.n; },
  arrow: () => this?.n,
};
console.log(
  o.normal(), o.arrow());

console.log(JSON.stringify({
  a: 1,
  b: undefined,
  c: null,
}));
